// git-trim: Automatically trims local tracking branches whose upstream branches
// are merged or stray. Reimplementation.

use std::env;
use std::fmt::Write as _;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

const BIN_NAME: &str = "executable";
const PROG_VERSION: &str = "git-trim 0.4.4";

// ---------- Help text ----------

fn short_help() -> String {
    let mut s = String::new();
    s.push_str("Automatically trims your tracking branches whose upstream branches are merged or stray.\n");
    s.push('\n');
    s.push_str(&format!("Usage: {BIN_NAME} [OPTIONS]\n"));
