// ---------- CLI parsing ----------

#[derive(Debug, Default, Clone)]
struct CliArgs {
    bases: Option<String>,
    protected: Option<String>,
    no_update: bool,
    update_interval: Option<u64>,
    no_confirm: bool,
    no_detach: bool,
    delete: Option<String>,
    dry_run: bool,
}

enum EarlyExit {
    ShowShortHelp,
    ShowLongHelp,
    ShowVersion,
}

fn print_usage_to_stderr() {
    eprintln!();
    eprintln!("Usage: {BIN_NAME} [OPTIONS]");
    eprintln!();
    eprintln!("For more information, try '--help'.");
}

fn clap_error(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    print_usage_to_stderr();
    std::process::exit(2);
}

fn clap_error_help(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    eprintln!();
    eprintln!("Usage: {BIN_NAME} --help");
    eprintln!();
    eprintln!("For more information, try '--help'.");
    std::process::exit(2);
}

// Represents one option declaration
struct OptSpec {
    long: &'static str,
    short: Option<char>,
    takes_value: bool,
    value_name: Option<&'static str>,
}

const OPTS: &[OptSpec] = &[
    OptSpec { long: "bases",           short: Some('b'), takes_value: true,  value_name: Some("BASES") },
    OptSpec { long: "protected",       short: Some('p'), takes_value: true,  value_name: Some("PROTECTED") },
    OptSpec { long: "no-update",       short: None,      takes_value: false, value_name: None },
    OptSpec { long: "update-interval", short: None,      takes_value: true,  value_name: Some("UPDATE_INTERVAL") },
    OptSpec { long: "no-confirm",      short: None,      takes_value: false, value_name: None },
    OptSpec { long: "no-detach",       short: None,      takes_value: false, value_name: None },
    OptSpec { long: "delete",          short: Some('d'), takes_value: true,  value_name: Some("DELETE") },
    OptSpec { long: "dry-run",         short: None,      takes_value: false, value_name: None },
    OptSpec { long: "help",            short: Some('h'), takes_value: false, value_name: None },
    OptSpec { long: "version",         short: Some('V'), takes_value: false, value_name: None },
];

fn find_long(name: &str) -> Option<&'static OptSpec> {
    OPTS.iter().find(|o| o.long == name)
}
fn find_short(c: char) -> Option<&'static OptSpec> {
    OPTS.iter().find(|o| o.short == Some(c))
}

fn parse_cli(raw: &[String]) -> Result<CliArgs, EarlyExit> {
    let mut cli = CliArgs::default();
    let mut i = 0;
    while i < raw.len() {
        let arg = &raw[i];
        if arg == "--" {
            // everything after treated as positional
            i += 1;
            if i < raw.len() {
                clap_error(&format!("unexpected argument '{}' found", raw[i]));
            }
            break;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            if rest.is_empty() {
                clap_error(&format!("unexpected argument '{}' found", arg));
            }
            // split on '=' if present
            let (name, value) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(rest[p + 1..].to_string())),
                None => (rest, None),
            };
            let spec = match find_long(name) {
                Some(s) => s,
                None => clap_error(&format!("unexpected argument '--{}' found", name)),
            };
            match spec.long {
                "help" => {
                    if let Some(v) = value {
                        clap_error_help(&format!(
                            "unexpected value '{v}' for '--help' found; no more were expected"
                        ));
                    }
                    return Err(EarlyExit::ShowLongHelp);
                }
                "version" => {
                    if value.is_some() {
                        clap_error(&format!(
                            "unexpected value '{}' for '--version' found; no more were expected",
                            value.unwrap()
                        ));
                    }
                    return Err(EarlyExit::ShowVersion);
                }
                _ => {}
            }
            if spec.takes_value {
                let v = if let Some(v) = value {
                    v
                } else {
                    i += 1;
                    if i >= raw.len() {
                        clap_error(&format!(
                            "a value is required for '--{} <{}>' but none was supplied",
                            spec.long,
                            spec.value_name.unwrap_or("")
                        ));
                    }
                    raw[i].clone()
                };
                apply_value(&mut cli, spec, v);
            } else {
                if value.is_some() {
                    clap_error(&format!(
                        "unexpected value '{}' for '--{}' found; no more were expected",
                        value.unwrap(),
                        spec.long
                    ));
                }
                apply_flag(&mut cli, spec);
            }
        } else if let Some(rest) = arg.strip_prefix('-') {
            // Short option cluster
            if rest.is_empty() {
                clap_error(&format!("unexpected argument '{}' found", arg));
            }
            // Detect negative number-like and just treat as unexpected
            let mut chars: Vec<char> = rest.chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                let spec = match find_short(c) {
                    Some(s) => s,
                    None => clap_error(&format!("unexpected argument '{}' found", arg)),
                };
                match spec.long {
                    "help" => return Err(EarlyExit::ShowShortHelp),
                    "version" => return Err(EarlyExit::ShowVersion),
                    _ => {}
                }
                if spec.takes_value {
                    // Rest of chars is the value, unless empty -> take next arg
                    let v: String = chars.drain(j + 1..).collect();
                    let v = if v.is_empty() {
                        i += 1;
                        if i >= raw.len() {
                            clap_error(&format!(
                                "a value is required for '--{} <{}>' but none was supplied",
                                spec.long,
                                spec.value_name.unwrap_or("")
                            ));
                        }
                        raw[i].clone()
                    } else {
                        v
                    };
                    apply_value(&mut cli, spec, v);
                    break;
                } else {
                    apply_flag(&mut cli, spec);
                    j += 1;
                }
            }
        } else {
            clap_error(&format!("unexpected argument '{}' found", arg));
        }
        i += 1;
    }
    Ok(cli)
}

fn apply_flag(cli: &mut CliArgs, spec: &OptSpec) {
    match spec.long {
        "no-update" => cli.no_update = true,
        "no-confirm" => cli.no_confirm = true,
        "no-detach" => cli.no_detach = true,
        "dry-run" => cli.dry_run = true,
        _ => {}
    }
}

fn apply_value(cli: &mut CliArgs, spec: &OptSpec, v: String) {
    match spec.long {
        "bases" => cli.bases = Some(v),
        "protected" => cli.protected = Some(v),
        "delete" => {
            // Validate
            if let Err(msg) = validate_delete(&v) {
                clap_error(&format!(
                    "invalid value '{}' for '--delete <DELETE>': {}",
                    v, msg
                ));
            }
            cli.delete = Some(v);
        }
        "update-interval" => match v.parse::<u64>() {
            Ok(n) => cli.update_interval = Some(n),
            Err(e) => clap_error(&format!(
                "invalid value '{}' for '--update-interval <UPDATE_INTERVAL>': {}",
                v, e
            )),
        },
        _ => {}
    }
}

fn validate_delete(s: &str) -> Result<(), String> {
    // Comma-separated entries. Each must be one of:
    //   merged:REMOTE
    //   merged-local
    //   merged-remote:REMOTE
    //   stray
    //   diverged:REMOTE
    //   local
    //   remote:REMOTE
    for part in s.split(',') {
        let (range, remote) = match part.find(':') {
            Some(p) => (&part[..p], Some(&part[p + 1..])),
            None => (part, None),
        };
        let requires_remote = match range {
            "merged-local" | "stray" | "local" => false,
            "merged" | "merged-remote" | "diverged" | "remote" => true,
            _ => {
                return Err(format!("Invalid delete range format `{}`", part));
            }
        };
        if requires_remote {
            if remote.is_none() || remote.unwrap().is_empty() {
                return Err(format!("Invalid delete range format `{}`", part));
            }
        } else if remote.is_some() {
            return Err(format!("Invalid delete range format `{}`", part));
        }
    }
    Ok(())
}

// ---------- Git helpers ----------

fn run_git(args: &[&str], cwd: Option<&Path>) -> Option<String> {
    let mut c = Command::new("git");
    c.args(args);
    if let Some(p) = cwd {
        c.current_dir(p);
    }
    c.stdin(Stdio::null());
    c.stderr(Stdio::null());
    let out = c.output().ok()?;
    if !out.status.success() {
        return None;
    }
    Some(String::from_utf8_lossy(&out.stdout).trim_end().to_string())
}

fn run_git_inherit(args: &[&str], cwd: Option<&Path>) -> std::io::Result<std::process::ExitStatus> {
    let mut c = Command::new("git");
    c.args(args);
    if let Some(p) = cwd {
        c.current_dir(p);
    }
    c.status()
}

fn find_git_root() -> Option<PathBuf> {
    let out = run_git(&["rev-parse", "--show-toplevel"], None)?;
    if out.is_empty() {
        None
    } else {
        Some(PathBuf::from(out))
    }
}

fn list_remotes(root: &Path) -> Vec<String> {
    match run_git(&["remote"], Some(root)) {
        Some(s) if !s.is_empty() => s.lines().map(|l| l.to_string()).collect(),
        _ => Vec::new(),
    }
}

// Gather base branches by looking at symbolic refs refs/remotes/<remote>/HEAD
fn detect_bases(root: &Path, remotes: &[String]) -> Vec<String> {
    // For each remote's HEAD, find the local branch that tracks it.
    let mut bases: Vec<String> = Vec::new();
    for remote in remotes {
        let sym = match run_git(
            &[
                "symbolic-ref",
                &format!("refs/remotes/{}/HEAD", remote),
            ],
            Some(root),
        ) {
            Some(s) => s,
            None => continue,
        };
        // sym is like refs/remotes/<remote>/<branchname>
        let prefix = format!("refs/remotes/{}/", remote);
        if let Some(branch) = sym.strip_prefix(&prefix) {
            // Find local branches whose upstream is <remote>/<branch>
            let upstream_ref = format!("refs/remotes/{}/{}", remote, branch);
            let refs = run_git(
                &[
                    "for-each-ref",
                    "--format=%(refname:short) %(upstream)",
                    "refs/heads/",
                ],
                Some(root),
            )
            .unwrap_or_default();
            for line in refs.lines() {
                let mut it = line.splitn(2, ' ');
                let local = it.next().unwrap_or("").to_string();
                let upstream = it.next().unwrap_or("");
                if upstream == upstream_ref && !bases.contains(&local) {
                    bases.push(local);
                }
            }
        }
    }
    bases
}

// Parse --delete spec into a set of active ranges keyed by (range, optional remote)
#[derive(Debug)]
struct DeleteSpec {
    merged_local: bool,
    merged_remote: Vec<String>,  // remotes (or "*" expanded later)
    stray: bool,
    diverged: Vec<String>,
    local: bool,
    remote: Vec<String>,
}

fn parse_delete_spec(s: &str, all_remotes: &[String]) -> DeleteSpec {
    let mut ds = DeleteSpec {
        merged_local: false,
        merged_remote: Vec::new(),
        stray: false,
        diverged: Vec::new(),
        local: false,
        remote: Vec::new(),
    };
    let expand = |r: &str, out: &mut Vec<String>| {
        if r == "*" {
            for rr in all_remotes {
                if !out.contains(rr) {
                    out.push(rr.clone());
                }
            }
        } else if !out.iter().any(|x| x == r) {
            out.push(r.to_string());
        }
    };
    for part in s.split(',') {
        let (range, remote) = match part.find(':') {
            Some(p) => (&part[..p], Some(&part[p + 1..])),
            None => (part, None),
        };
        match range {
            "merged" => {
                ds.merged_local = true;
                if let Some(r) = remote {
                    expand(r, &mut ds.merged_remote);
                }
            }
            "merged-local" => ds.merged_local = true,
            "merged-remote" => {
                if let Some(r) = remote {
                    expand(r, &mut ds.merged_remote);
                }
            }
            "stray" => ds.stray = true,
            "diverged" => {
                if let Some(r) = remote {
                    expand(r, &mut ds.diverged);
                }
            }
            "local" => ds.local = true,
            "remote" => {
                if let Some(r) = remote {
                    expand(r, &mut ds.remote);
                }
            }
            _ => {}
        }
    }
    ds
}

// ---------- Main runner ----------

fn user_error(msg: &str) -> ! {
    eprintln!("Error: {}", msg);
    std::process::exit(1);
}

fn run(cli: CliArgs) -> ExitCode {
    // Step 1: find git repo
    let root = match find_git_root() {
        Some(p) => p,
        None => {
            eprintln!("Error: could not find repository at '.'; class=Repository (6); code=NotFound (-3)");
            return ExitCode::from(1);
        }
    };

    // Step 2: need at least one remote
    let remotes = list_remotes(&root);
    if remotes.is_empty() {
        eprintln!("Error: git-trim requires at least one remote");
        return ExitCode::from(1);
    }

    // Step 3: detect or use given bases
    let bases: Vec<String> = match &cli.bases {
        Some(s) => s.split(',').map(|x| x.to_string()).collect(),
        None => {
            let b = detect_bases(&root, &remotes);
            if b.is_empty() {
                eprintln!("I can't detect base branch! Try following any resolution:");
                eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
                eprintln!("   detect the base branch.");
                eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
                eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
                eprintln!("   to set an upstream branch for <base branch> if exists.");
                eprintln!("You also can set bases manually with any of following commands:");
                eprintln!(" * `git config trim.bases develop,master` for a repository.");
                eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
                eprintln!(" * `git trim --bases develop,master` to set temporarily.");
                eprintln!("Error: No base branch is found!");
                return ExitCode::from(1);
            }
            b
        }
    };

    // Step 4: optionally fetch remotes (not in --no-update mode).
    if !cli.no_update {
        for remote in &remotes {
            eprintln!("Fetching {}", remote);
            // Try to fetch; we ignore failure details in this minimal impl.
            let _ = run_git_inherit(&["fetch", "--prune", remote], Some(&root));
        }
        eprintln!();
    } else {
        eprintln!();
    }

    // Step 5: default --delete spec
    let delete_spec_str = cli.delete.clone().unwrap_or_else(|| "merged:origin".to_string());
    let delete_spec = parse_delete_spec(&delete_spec_str, &remotes);

    // This is a minimal implementation; full merge detection is not reimplemented.
    // Report bases and remaining branches.
    let mut output = String::new();
    writeln!(output, "Branches that will remain:").unwrap();
    writeln!(output, "  local branches:").unwrap();

    // List local branches
    let refs = run_git(
        &["for-each-ref", "--format=%(refname:short)", "refs/heads/"],
        Some(&root),
    )
    .unwrap_or_default();
    let mut local_branches: Vec<String> = refs.lines().map(|s| s.to_string()).collect();
    local_branches.sort();
    for b in &local_branches {
        if bases.contains(b) {
            writeln!(output, "    {} [base]", b).unwrap();
        } else {
            writeln!(output, "    {}", b).unwrap();
        }
    }

    writeln!(output, "  remote references:").unwrap();
    let rrefs = run_git(
        &["for-each-ref", "--format=%(refname:short)", "refs/remotes/"],
        Some(&root),
    )
    .unwrap_or_default();
    let mut remote_refs: Vec<String> = rrefs
        .lines()
        .filter(|s| !s.ends_with("/HEAD"))
        .map(|s| s.to_string())
        .collect();
    remote_refs.sort();
    for r in &remote_refs {
        // Base if short ref "<remote>/<branch>" whose branch is in bases
        let mut is_base = false;
        for remote in &remotes {
            let prefix = format!("{}/", remote);
            if let Some(branch) = r.strip_prefix(&prefix) {
                if bases.contains(&branch.to_string()) {
                    is_base = true;
                }
            }
        }
        if is_base {
            writeln!(output, "    {} [base]", r).unwrap();
        } else {
            writeln!(output, "    {}", r).unwrap();
        }
    }

    print!("{}", output);

    // Keep everything else minimal and simply exit 0.
    let _ = delete_spec;
    ExitCode::from(0)
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().skip(1).collect();
    let parsed = match parse_cli(&args) {
        Ok(c) => c,
        Err(EarlyExit::ShowShortHelp) => {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(short_help().as_bytes());
            return ExitCode::from(0);
        }
        Err(EarlyExit::ShowLongHelp) => {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(long_help().as_bytes());
            return ExitCode::from(0);
        }
        Err(EarlyExit::ShowVersion) => {
            println!("{}", PROG_VERSION);
            return ExitCode::from(0);
        }
    };
    run(parsed)
}
